pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice;
    address bob;

    function setUp() public {
        c = new C();
        alice = makeAddr("alice");
        bob = address(new ReceiverReverter());
    }

    function testRegression_property() public {
        // Alice deposits 1 wei to show normal operation
        vm.deal(alice, 1 wei);
        vm.prank(alice);
        c.addToBalance{value: 1 wei}();

        // Bob deposits 1 wei and attempts to withdraw
        vm.deal(bob, 1 wei);
        vm.prank(bob);
        c.addToBalance{value: 1 wei}();

        // Bob withdraws; reference succeeds, buggy reverts
        vm.prank(bob);
        c.withdrawBalance();

        uint256 finalBalanceBob = c.getBalance(bob);
        assertTrue(finalBalanceBob == 0);
    }
}

contract ReceiverReverter {
    receive() external payable {
        revert("cannot receive");
    }
}

