pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up a specific scenario: call addToBalance with value 0
        vm.deal(address(0x1234), 1 ether);
        vm.prank(address(0x1234));
        c.addToBalance{value: 0}();

        // After this call, the reference contract (with require) would have reverted
        // because (userBalance[msg.sender] + 0) >= userBalance[msg.sender] is always true,
        // so the require passes and adds 0 to balance. The buggy version also adds 0.
        // Now withdraw balance - for reference, balance is 0, withdraw reverts on empty call
        // For buggy version, balance is 0, withdraw also reverts on empty call
        // This test scenario doesn't trigger the difference described. Let's try a different one.

        // Use value that could overflow: max uint256
        vm.deal(address(0x5678), type(uint256).max);
        vm.prank(address(0x5678));
        c.addToBalance{value: type(uint256).max}();

        // Reference contract would revert due to overflow check in require
        // Buggy contract would allow overflow
        // We need to check if the call reverted
        bool ok;
        vm.deal(address(0x9abc), 0);
        vm.prank(address(0x9abc));
        try c.addToBalance{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference allows this, bug allows this - assertion would pass for both
        // Need different approach

        // Let's use a simple overflow scenario
        // First deposit some ether to get a balance
        vm.deal(address(0xdef1), 10 ether);
        vm.prank(address(0xdef1));
        c.addToBalance{value: 1 ether}();

        // Now try to add more ether to cause overflow (if no require check)
        // Reference's require would fail if userBalance + value < userBalance (overflow)
        // Buggy would overflow
        bool success;
        vm.deal(address(0xdef1), 1 ether);
        vm.prank(address(0xdef1));
        try c.addToBalance{value: type(uint256).max - 1 ether + 1}() {
            success = true;
        } catch {
            success = false;
        }
        // Reference reverts because 1 ether + (max - 1 ether + 1) = 0 < 1 ether
        // Buggy does not revert, so success is true for buggy, false for reference
        assertTrue(!success, "Reference reverts on overflow, bug does not");
    }
}

