pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.addToBalance{value: 1 ether}();
        uint256 balBefore = address(c).balance;
        // withdraw all
        vm.prank(address(0x1));
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));
        assertTrue(success);
        uint256 balAfter = address(c).balance;
        // In reference, require ensures no overflow on addition, but overflow is impossible here.
        // Both should have balAfter == 0. To diverge, we need a case where reference reverts and bug doesn't.
        // But with Solidity 0.8.0, overflow in addition reverts regardless of require.
        // Since the require is redundant, no divergence. This test will pass on both (false positive).
        assertTrue(balAfter == 0);
    }
}

